import {CASTING_MEDIA} from './expedition-media-data.mjs';
import {equipmentName} from './expedition-equipment.mjs';
import {HEROES,GEAR,SKILLS,POS,roomsFor} from './expedition-data.mjs';
import {BUILDS} from './expedition-builds.mjs';
import {growth} from './expedition-growth.mjs';
import {companionPreview} from './expedition-command-preview.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const modes={round:'每回合一次',repeat:'持续',once:'一次',cycle:'轮转'},stock={herb:'药草',rune:'符纸',arrow:'箭矢'};
export function commandHome(g,config,previews={},roomId=''){
 const own=HEROES.find(h=>h.id===g.command?.heroId),member=g.members.find(h=>h.id===own?.id),rooms=roomsFor(config);
 return `<section class="guild-panel command-home" data-guild-pane="hero"><p class="eyebrow">个人英雄 / 伙伴协作</p><h2>${own?own.name+'，带上伙伴再次出发。':'选择你在远征中的英雄'}</h2><p>你专注自己的技能与成长，伙伴按选定职责执行战前指令。仍可自由调整全队站位、装备与高级战术。</p><div class="command-heroes">${HEROES.filter(h=>g.lineup.includes(h.id)).map(h=>`<button data-own-hero="${h.id}" aria-pressed="${own?.id===h.id}" ${g.pending?'disabled':''}><span aria-hidden="true" class="portrait ${h.portrait}"></span><strong>${h.name}</strong><span>${h.role}</span><small>${own?.id===h.id?'我的英雄':'选择此英雄'}</small></button>`).join('')}</div><p>切换主角不转移装备或经验；伙伴初始保留现有自定义指令。</p>${own?`<p class="personal-summary">${own.name} · ${['','初入','熟练','资深'][growth(member).level]} · 可用经验 ${member.xp} · 当前装备 ${equipmentName(member.gear)}</p><div class="bar"><button class="primary" data-personal="growth">我的成长与训练 →</button><button data-personal="equipment">我的装备 →</button><button data-personal="tactics">我的战术 →</button></div><h3>伙伴职责 · 预览后应用</h3><label>预览房间 <select id="companion-room">${rooms.map(r=>`<option value="${r.id}" ${(roomId||rooms[0].id)===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><p>初始站位下的覆盖与目标候选；不预测战中存活、机关分支或资源余量。预览不修改已保存职责，出征使用已应用的职责。</p><details><summary>职责接管哪些设置？</summary><p>接管专修、预备、普通与预设提供的治疗指令，忽略对应逐房指令覆盖；保留站位、防御、道具、实际装备与训练。不会自动购买或训练。自定义使用准备页指令；实验试跑也使用准备页草稿。</p></details><div class="companion-grid">${HEROES.filter(h=>g.lineup.includes(h.id)&&h.id!==own.id).map(h=>{
 const saved=g.command.companions[h.id]||'custom',mode=previews[h.id]??saved,changed=mode!==saved,p=companionPreview(g,config,h.id,mode,roomId),rolePlan=BUILDS[h.id].find(b=>b.id===mode);
 return `<article><h3>${h.name} · ${h.role}</h3><p class="companion-saved">已应用：${BUILDS[h.id].find(b=>b.id===saved)?.name||'自定义指令'}</p><label>预览职责 <select data-companion="${h.id}" aria-label="${h.name}的伙伴职责" ${g.pending?'disabled':''}><option value="custom" ${mode==='custom'?'selected':''}>自定义指令</option>${BUILDS[h.id].map(b=>`<option value="${b.id}" ${mode===b.id?'selected':''}>${b.name}</option>`).join('')}</select></label><p class="${changed?'ready-diff':''}">${changed?'预览尚未应用；出征仍使用上方已应用职责。':'预览与当前职责一致。'}</p>${rolePlan?`<p>${esc(rolePlan.desc)}</p>`:''}<div class="bar"><button data-apply-companion="${h.id}" ${!changed||g.pending?'disabled':''}>应用此职责</button>${changed?`<button data-cancel-companion="${h.id}">取消预览</button>`:''}</div><details class="companion-preview"><summary>查看指令与覆盖 · ${esc(p.roomName)}</summary>${p.rows.map(r=>`<div class="preview-command"><b>${r.phase==='prep'?'预备':'普通'} · ${r.name}${r.medium?' / '+CASTING_MEDIA[r.medium].name:''} → ${r.target}</b><small>${modes[r.mode]} · 每次 ${r.cost} 法力${r.item?' / '+(r.itemAmount??1)+stock[r.item]:''}</small><p>${r.kind==='buff'?'覆盖：':r.kind==='attack'?'候选：':r.kind==='summon'?'召唤位置：':'目标规则：'}${r.kind==='recall'?'仅本人当时存活的召唤物':r.kind==='summon'?r.target:esc(r.candidates.join('、')||'无')}${r.kind==='attack'?`（每次最多${r.max||1}个，候选不等于实际命中）`:''}</p>${r.warnings.map(w=>`<p class="ready-diff">${w}</p>`).join('')}</div>`).join('')}${p.healing.enabled?`<p>救护：≤${Math.round(p.healing.threshold*100)}%生命，${POS[p.healing.target]||{all:'全队',self:'自身'}[p.healing.target]}，${p.healing.priority==='self_first'?'优先自保':'最低生命比例'}。实际选择随战中状态变化。</p>`:'<p>条件救护未启用。</p>'}</details><button data-ready-edit="${h.id}" ${g.pending?'disabled':''}>切到自定义并编辑</button></article>`;
 }).join('')}</div><button data-guild-tab="departure" class="primary">核对实际队伍并出征 →</button>`:''}</section>`;
}
